"C:\\WINDOWS\\System32\\WindowsPowerShell\\v1.0\\powershell.exe" -Command '$dir='"'C:\\Users\\EDY\\Desktop\\新建文件夹\\offline-activity-audit\\input\\.prepared\\20260814-live-003\\sources\\promotional_display\\核销资料-诚成26年4月【堆头20家】\\堆头照片'; "'$env:AUDIT_PHOTO_DIR=$dir; @'"'
import os,json,hashlib
from PIL import Image,ExifTags
import numpy as np, cv2
root=os.environ['AUDIT_PHOTO_DIR']

def phash(im, n=8, high=32):
    g=np.array(im.convert('L').resize((high,high),Image.Resampling.LANCZOS),dtype=np.float32)
    d=cv2.dct(g)[:n,:n]
    med=np.median(d.flatten()[1:])
    bits=(d>med).flatten()
    return ''.join('1' if x else '0' for x in bits)
def dhash(im,n=8):
    g=np.array(im.convert('L').resize((n+1,n),Image.Resampling.LANCZOS))
    bits=(g[:,1:]>g[:,:-1]).flatten()
    return ''.join('1' if x else '0' for x in bits)
def hexd(bits): return hex(int(bits,2))[2:].zfill(len(bits)//4)
def ham(a,b): return sum(x"'!=y for x,y in zip(a,b))
rows=[]
for fn in sorted(os.listdir(root), key=lambda s:s.casefold()):
    p=os.path.join(root,fn)
    if not os.path.isfile(p): continue
    with open(p,'"'rb') as f: sha=hashlib.sha256(f.read()).hexdigest()
    im=Image.open(p)
    ex={}
    raw=im.getexif()
    for k,v in raw.items():
        name=ExifTags.TAGS.get(k,str(k))
        if name in {'DateTime','DateTimeOriginal','DateTimeDigitized','GPSInfo','Make','Model','Software','Orientation'}:
            if name=='GPSInfo' and isinstance(v,dict):
                v={ExifTags.GPSTAGS.get(kk,str(kk)):str(vv) for kk,vv in v.items()}
            ex[name]=str(v)
    pb=phash(im); db=dhash(im)
    rows.append({'filename':fn,'size':list(im.size),'mode':im.mode,'sha256':sha,'phash64':hexd(pb),'dhash64':hexd(db),'_pb':pb,'_db':db,'exif':ex})
pairs=[]
for i in range(len(rows)):
  for j in range(i+1,len(rows)):
    pd=ham(rows[i]['_pb'],rows[j]['_pb']); dd=ham(rows[i]['_db'],rows[j]['_db'])
    if pd<=16 or dd<=12:
      pairs.append({'a':rows[i]['filename'],'b':rows[j]['filename'],'phash_distance':pd,'dhash_distance':dd})
for x in rows: x.pop('_pb'); x.pop('_db')
print(json.dumps({'files':rows,'low_distance_pairs':sorted(pairs,key=lambda x:(x['phash_distance'],x['dhash_distance']))},ensure_ascii=False,indent=2))
